        self.emit_relationship_signal_background(
            "oracle",
            &verdict.governance.love_equation_guard,
            verdict.query_id.clone(),
        );
        self.append_verdict(&verdict)?;
        self.persist_snapshot(&self.snapshot().await?)?;
        Ok(verdict)
    }

